CREATE OR REPLACE FUNCTION public.get_or_create_invoice(p_user_id uuid, p_card_id uuid, p_transaction_date date)
 RETURNS uuid
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_closing_day INTEGER;
    v_due_day INTEGER;
    v_ref_month INTEGER;
    v_ref_year INTEGER;
    v_invoice_id UUID;
    v_closing_date DATE;
    v_due_date DATE;
    v_transaction_day INTEGER;
BEGIN
    -- Busca dados do cartão
    SELECT closing_day, due_day
    INTO v_closing_day, v_due_day
    FROM credit_cards
    WHERE id = p_card_id;

    v_transaction_day := EXTRACT(DAY FROM p_transaction_date);

    -- LÓGICA DE FECHAMENTO CORRETA
    -- Compra antes do fechamento → fatura do mesmo mês
    -- Compra no ou após fechamento → fatura do próximo mês
    IF v_transaction_day < v_closing_day THEN
        v_ref_month := EXTRACT(MONTH FROM p_transaction_date);
        v_ref_year  := EXTRACT(YEAR  FROM p_transaction_date);
    ELSE
        v_ref_month := EXTRACT(MONTH FROM (p_transaction_date + INTERVAL '1 month'));
        v_ref_year  := EXTRACT(YEAR  FROM (p_transaction_date + INTERVAL '1 month'));
    END IF;

    -- Busca fatura existente
    SELECT id
    INTO v_invoice_id
    FROM credit_card_invoices
    WHERE credit_card_id = p_card_id
      AND reference_month = v_ref_month
      AND reference_year  = v_ref_year;

    -- Cria fatura se não existir
    IF v_invoice_id IS NULL THEN

        -- Data de fechamento
        v_closing_date :=
            make_date(v_ref_year, v_ref_month, 1)
            + (v_closing_day - 1) * INTERVAL '1 day';

        -- Data de vencimento
        IF v_due_day < v_closing_day THEN
            -- Vencimento no mês seguinte
            v_due_date :=
                (make_date(v_ref_year, v_ref_month, 1) + INTERVAL '1 month')
                + (v_due_day - 1) * INTERVAL '1 day';
        ELSE
            -- Vencimento no mesmo mês
            v_due_date :=
                make_date(v_ref_year, v_ref_month, 1)
                + (v_due_day - 1) * INTERVAL '1 day';
        END IF;

        INSERT INTO credit_card_invoices (
            user_id,
            credit_card_id,
            reference_month,
            reference_year,
            status,
            closing_date,
            due_date,
            total_amount,
            paid_amount
        )
        VALUES (
            p_user_id,
            p_card_id,
            v_ref_month,
            v_ref_year,
            'open',
            v_closing_date,
            v_due_date,
            0,
            0
        )
        RETURNING id INTO v_invoice_id;
    END IF;

    RETURN v_invoice_id;
END;
$function$

